import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import fixtures from "../../fixtures/scenario-fixtures.json";
import type { Merchant } from "./config";
import { HttpError } from "./http";

/** Generated by `npm run setup:plans`; holds PayPal IDs only, never credentials. */
export const planMappingPath = fileURLToPath(new URL("../../paypal-plans.json", import.meta.url));

export type PlanMapping = Record<string, { productId: string; paypalPlanId: string }>;

export interface SubscriptionPlan {
  planId: string;
  merchant: Merchant;
  providerId: "provider_a" | "provider_b";
  recurringMinor: number;
  introductoryMinor?: number;
  introductoryCycles?: number;
  paypalPlanId: string;
}

export function merchantForProvider(providerId: string): Merchant | null {
  if (providerId === "provider_a") return "A";
  return providerId === "provider_b" ? "B" : null;
}

/** The authored plans (a_01, a_02, b_01, b_02) and their prices come from the shared fixtures. */
export const fixturePlans = fixtures.providerPlans.map((plan) => ({
  planId: plan.planId,
  merchant: merchantForProvider(plan.providerId)!,
  providerId: plan.providerId as SubscriptionPlan["providerId"],
  recurringMinor: plan.recurringMinor,
  ...("introductoryMinor" in plan && "introductoryCycles" in plan
    ? { introductoryMinor: plan.introductoryMinor, introductoryCycles: plan.introductoryCycles }
    : {}),
}));

export function readPlanMapping(path = planMappingPath): PlanMapping {
  return existsSync(path) ? JSON.parse(readFileSync(path, "utf8")) : {};
}

export function resolveSubscriptionPlan(mapping: PlanMapping, planId: string): SubscriptionPlan {
  const plan = fixturePlans.find((candidate) => candidate.planId === planId);
  const paypalPlanId = mapping[planId]?.paypalPlanId;
  if (!plan || !paypalPlanId)
    throw new HttpError(
      503,
      "plans_not_configured",
      `PayPal plan ${planId} has not been set up; run npm run setup:plans.`,
    );
  return { ...plan, paypalPlanId };
}
